// Generated by Locksmith (smith init). Blocks the tool call when the hook denies or is unavailable.
import { spawnSync } from "node:child_process";

const COMMAND = "command -v smith >/dev/null 2>&1 || { echo 'Locksmith hook unavailable: run smith doctor' >&2; exit 2; }; smith hook opencode tool.execute.before";

export const Locksmith = async () => ({
  "tool.execute.before": async (input, output) => {
    const r = spawnSync("sh", ["-c", COMMAND], {
      input: JSON.stringify({ tool: input.tool, args: output.args }),
      encoding: "utf8",
      timeout: 10000,
    });
    if (r.error || r.status !== 0) {
      throw new Error((r.stderr || "").trim() || "Locksmith hook unavailable: run smith doctor");
    }
  },
});
